<?php
session_start(); require '../database/config.php'; require '../includes/auth.php'; requireCustomer();
$pdo=getConnection(); $rooms=$pdo->query("SELECT r.*,d.location,d.name FROM rooms r JOIN dormitories d ON d.id=r.dormitory_id WHERE r.status='available' AND r.available_slots>0 AND d.status='active' ORDER BY d.location,r.room_number")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Available Rooms | Obeda Dormitories</title><link rel="stylesheet" href="../assets/css/customer.css"></head><body><header class="customer-header"><a href="../index.php"><img src="../assets/images/logo-dark.svg" alt="Obeda Dormitories"></a><nav><a href="dashboard.php">Dashboard</a><a href="viewing.php">Viewing</a><a class="active" href="rooms.php">Rooms</a><a href="application.php">My Applications</a><a href="profile.php">Profile</a></nav><div><span><?=h($_SESSION['first_name'])?></span><a href="../logout.php">Logout</a></div></header><main class="customer-main"><h1>Available Rooms</h1><div class="room-grid"><?php foreach($rooms as $r): ?><article class="panel room-card"><h2><?=h($r['location'])?> — Room <?=h($r['room_number'])?></h2><p><strong>Type:</strong> <?=h(ucwords(str_replace('_',' ',$r['room_type'])))?></p><p><strong>Capacity:</strong> <?=h((string)$r['capacity'])?></p><p><strong>Available slots:</strong> <?=h((string)$r['available_slots'])?></p><p><strong>Monthly rate:</strong> ₱<?=number_format((float)$r['monthly_rate'],2)?></p><a class="button" href="application.php?room_id=<?=h((string)$r['id'])?>">Apply for this room</a></article><?php endforeach; if(!$rooms): ?><section class="panel"><p>There are currently no rooms marked available. Please check again later or schedule a viewing.</p></section><?php endif; ?></div></main></body></html>
